def normalize_text(text: str) -> str:
    t = text.lower()
    mapping = {
        'ı': 'i', 'ğ': 'g', 'ü': 'u', 'ş': 's', 'ö': 'o', 'ç': 'c',
        'İ': 'i', 'Ğ': 'g', 'Ü': 'u', 'Ş': 's', 'Ö': 'o', 'Ç': 'c'
    }
    for k, v in mapping.items():
        t = t.replace(k, v)
    return t

def translate_to_english(text: str) -> str:
    if not text or not text.strip():
        return ""

    text = text.strip()
    if text in _TRANSLATION_CACHE:
        return _TRANSLATION_CACHE[text]
    norm = normalize_text(text)

    # Hizli kaldirma kurali kontrolu
    if any(rm in norm for rm in ["kaldir", "cikar", "sil", "yok et"]):
        for tr_word, en_word in FAST_DICTIONARY.items():
            if tr_word in norm and en_word not in ["remove", "turn into", "replace with"]:
                res = f"remove {en_word}, natural background, realistic skin and texture"
                _TRANSLATION_CACHE[text] = res
                return res

    try:
        translated = GoogleTranslator(source='auto', target='en').translate(text)
        if translated:
            _TRANSLATION_CACHE[text] = translated
            return translated
    except Exception as e:
        print(f"Ceviri hatasi (Yerel sozluk devreye girdi): {e}")

    # Offline / Rate-limit yerel sozluk fallback
    out_words = norm
    for tr_k, en_v in sorted(FAST_DICTIONARY.items(), key=lambda x: -len(x[0])):
        out_words = out_words.replace(tr_k, en_v)
    _TRANSLATION_CACHE[text] = out_words
    return out_words

def parse_target_and_prompt(text: str):
    norm = normalize_text(text)
    en_text = translate_to_english(text).lower()

    clothing_keywords = [
        "pants", "trousers", "jeans", "shorts", "skirt", "dress",
        "jacket", "coat", "hoodie", "shirt", "t-shirt", "sweater",
        "shoes", "hat", "glasses", "sunglasses", "hair", "beard"
    ]

    target_object = None
    for kw in clothing_keywords:
        if kw in en_text:
            target_object = kw
            break

    if not target_object:
        words = en_text.split()
        target_object = words[-1] if words else "object"

    is_removal = any(r in en_text for r in ["remove", "take off", "delete", "without", "clear"])
    if is_removal:
        replacement = "seamless natural texture, high quality, clean background, matching anatomy"
    else:
        replacement = en_text

    return target_object, replacement

